def zentral_uebernehmen(apps, schema_editor):
    """Bisher je Ausgabestelle eingeschaltet: zentral „nur ausgewählte“, die größte Handy-Zahl."""
    stellen = apps.get_model("aufruf", "AufrufEinstellungen").objects.filter(handy=True)
    zahlen = list(stellen.values_list("handy_geraete", flat=True))
    apps.get_model("aufruf", "HandyEinstellungen").objects.update_or_create(
        pk=1, defaults={"modus": "auswahl" if zahlen else "aus", "geraete": max(zahlen or [2])},
    )


def zurueck(apps, schema_editor):
    zentral = apps.get_model("aufruf", "HandyEinstellungen").objects.filter(pk=1).first()
    stellen = apps.get_model("aufruf", "AufrufEinstellungen").objects.all()
    if zentral:
        stellen.update(handy_geraete=zentral.geraete)
        if zentral.modus == "alle":
            stellen.update(handy=True)
        elif zentral.modus == "aus":
            stellen.update(handy=False)


